(()=>{'use strict';
const P=window.PerturbationPhysics,$=id=>document.getElementById(id),TAU=Math.PI*2,C=window.BookTheme.palette({gold:'#e4c389',cyan:'#7abdc4',sage:'#b5cebb'}),key='galaxies-chapter-4-labs';
const s={amplitude:.035,phase:0,ratio:1.5,tau:1.5,matter:.3,a:.5,norm:'early',strength:.5,gamma:.21,logk:-1,n:1,kind:'T'};
try{const v=JSON.parse(localStorage.getItem(key)||'{}');for(const [k,lo,hi] of [['amplitude',0,.05],['phase',0,9999],['ratio',.4,2],['tau',0,3],['matter',.1,1],['a',.05,1],['strength',0,.9],['gamma',.1,.4],['logk',-3,1],['n',.8,1.2]])if(typeof v[k]==='number'&&Number.isFinite(v[k]))s[k]=Math.max(lo,Math.min(hi,v[k]));s.phase=Math.round(s.phase);if(['early','today'].includes(v.norm))s.norm=v.norm;if(['T','power'].includes(v.kind))s.kind=v.kind;}catch{}
function save(){try{localStorage.setItem(key,JSON.stringify(s));}catch{}}
const fmt=(n,d=3)=>(Math.abs(n)<.5*10**(-d)?0:n).toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d});
const sci=n=>Math.abs(n)<.001&&n!==0?n.toExponential(2):fmt(n,3);
const controls=[['field-amplitude','amplitude'],['jeans-ratio','ratio'],['jeans-time','tau'],['growth-matter','matter'],['growth-a','a'],['sheet-strength','strength'],['transfer-gamma','gamma'],['transfer-k','logk'],['spectral-n','n']];controls.forEach(([id,k])=>$(id).value=s[k]);$('growth-normalization').value=s.norm;$('transfer-kind').value=s.kind;
const bind=(id,k,fn)=>$(id).addEventListener('input',e=>{s[k]=+e.target.value;save();fn();});
const running=new Map(),labels={'field-play':'演示振幅增长','jeans-play':'播放模式演化','sheet-play':'播放薄层形成'};
function stop(id){const r=running.get(id);if(r)cancelAnimationFrame(r.frame);running.delete(id);$(id).textContent=labels[id];$(id).setAttribute('aria-pressed','false');save();}
function play(id,k,input,start,end,render,duration=8000){if(running.has(id)){stop(id);return;}if(s[k]>=end-1e-6)s[k]=start;const from=s[k],t0=performance.now(),run={frame:0,last:-100};running.set(id,run);$(id).textContent='暂停';$(id).setAttribute('aria-pressed','true');function frame(now){const p=Math.min(1,(now-t0)/duration);s[k]=from+(end-from)*p;$(input).value=s[k];if(now-run.last>30||p===1){render();run.last=now;}if(p<1)run.frame=requestAnimationFrame(frame);else{stop(id);$(id).textContent='重新播放';}}run.frame=requestAnimationFrame(frame);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)for(const id of [...running.keys()])stop(id);});
function canvas(id){const c=$(id),rect=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);c.width=Math.round(rect.width*d);c.height=Math.round(rect.height*d);const ctx=c.getContext('2d');ctx.setTransform(d,0,0,d,0,0);return {c,ctx,w:rect.width,h:rect.height};}
function logTicks(domain){const a=Math.ceil(Math.log10(domain[0])),b=Math.floor(Math.log10(domain[1])),step=Math.max(1,Math.ceil((b-a+1)/7));return d3.range(a,b+1,step).map(p=>10**p);}
function tick(n){return n!==0&&(Math.abs(n)<.001||Math.abs(n)>=10000)?n.toExponential(0):d3.format('~g')(n);}
function plot(id,x,y,xTitle,yTitle){return window.BookCharts.frame(id,{x,y,xLabel:xTitle,yLabel:yTitle});}
function curve(p,data,x,y,color,dash,label){const points=data.map(d=>({x:x(d),y:y(d)})),index=BookCharts.addSeries(p.node||p.svg.node(),points,label);return p.svg.append('path').datum(points).attr('data-plot-series',index).attr('d',d3.line().x(d=>p.x(d.x)).y(d=>p.y(d.y))).attr('fill','none').attr('stroke',color).attr('stroke-width',1.8).attr('stroke-dasharray',dash||null);}
function selected(p,x,y,color=C.gold,seriesIndex=0){BookCharts.includeSample(p.node||p.svg.node(),seriesIndex,x,y);p.svg.append('line').attr('x1',p.x(x)).attr('x2',p.x(x)).attr('y1',p.m.top).attr('y2',p.h-p.m.bottom).attr('stroke',window.BookTheme.color('#bbcecb')).attr('stroke-dasharray','4 4');p.svg.append('circle').attr('cx',p.x(x)).attr('cy',p.y(y)).attr('data-model-point-series',seriesIndex).attr('data-model-point-x',x).attr('data-model-point-y',y).attr('r',4).attr('fill',color);}
const rawModes=[[1,0,1],[0,1,.9],[1,1,.7],[2,-1,.6],[1,-2,.5],[2,2,.4],[3,1,.32],[1,3,.28],[3,-2,.24],[4,1,.2],[2,-4,.17],[4,3,.14],[5,-1,.12],[1,5,.1],[6,2,.08],[3,5,.06]],normalization=Math.sqrt(rawModes.reduce((sum,v)=>sum+v[2]**2/2,0));
let modes=[],fieldCache=[],sliceCache=[],fieldMean=0,fieldRms=0;
const tile=document.createElement('canvas');tile.width=160;tile.height=96;const tileCtx=tile.getContext('2d');
function cacheField(){let seed=13871+s.phase*109;function random(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;}modes=rawModes.map(([kx,ky,amplitude])=>({kx,ky,amplitude:amplitude/normalization,phase:random()*TAU}));fieldCache=[];fieldMean=0;fieldRms=0;for(let y=0;y<96;y++)for(let x=0;x<160;x++){const v=P.modeField(x/160,y/96,modes);fieldCache.push(v);fieldMean+=v;fieldRms+=v*v;}fieldMean/=fieldCache.length;fieldRms=Math.sqrt(fieldRms/fieldCache.length);sliceCache=d3.range(241).map(i=>({x:i/240,v:P.modeField(i/240,.5,modes)}));}
function density(){const {c,ctx,w,h}=canvas('density-field'),img=tileCtx.createImageData(160,96),scale=d3.scaleLinear().domain([-.2,0,.2]).range([window.BookTheme.color('#63aebd'),window.BookTheme.color('#11222a'),window.BookTheme.color('#f1ce8c')]).clamp(true);fieldCache.forEach((v,i)=>{const col=d3.rgb(scale(v*s.amplitude));img.data.set([col.r,col.g,col.b,255],i*4);});tileCtx.putImageData(img,0,0);const top=w<600?109:84,bottom=35;ctx.imageSmoothingEnabled=true;ctx.drawImage(tile,0,top,w,h-top-bottom);ctx.strokeStyle=window.BookTheme.color('#d7e8e4aa');ctx.setLineDash([5,7]);ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,top+(h-top-bottom)/2);ctx.lineTo(w,top+(h-top-bottom)/2);ctx.stroke();ctx.setLineDash([]);$('field-amplitude-value').textContent=fmt(s.amplitude);const min=Math.min(...fieldCache)*s.amplitude,max=Math.max(...fieldCache)*s.amplitude;$('field-result').textContent=`平均 δ=${fmt(fieldMean*s.amplitude,4)}；均方根 δ=${fmt(fieldRms*s.amplitude)}；当前范围 ${fmt(min)} 至 ${fmt(max)}。16 个模式，固定色标 −0.2…+0.2；相位组 ${s.phase+1}。`;c.setAttribute('aria-label',`合成二维密度反差场，相位组${s.phase+1}，均方根${fmt(s.amplitude)}，范围${fmt(min)}至${fmt(max)}，零均值。`);const p=plot('density-slice',d3.scaleLinear().domain([0,1]),d3.scaleLinear().domain([-.2,.2]),'归一化共动位置 x','中央剖面 δ');p.svg.append('line').attr('x1',p.x(0)).attr('x2',p.x(1)).attr('y1',p.y(0)).attr('y2',p.y(0)).attr('stroke',window.BookTheme.color('#5b757d')).attr('stroke-dasharray','3 5');curve(p,sliceCache,d=>d.x,d=>s.amplitude*d.v,C.gold);}
cacheField();bind('field-amplitude','amplitude',()=>{stop('field-play');density();});$('field-phase').addEventListener('click',()=>{s.phase=(s.phase+1)%10000;save();cacheField();density();});$('field-reset').addEventListener('click',()=>{stop('field-play');s.phase=0;s.amplitude=.035;$('field-amplitude').value=s.amplitude;save();cacheField();density();});$('field-play').addEventListener('click',()=>play('field-play','amplitude','field-amplitude',0,.05,density));
function jeans(){const v=P.jeans(s.ratio,s.tau),data=d3.range(151).map(i=>({t:i/50,d:P.jeans(s.ratio,i/50).delta/.01})),max=Math.max(1.2,d3.max(data,d=>d.d)*1.08);$('jeans-ratio-value').textContent=fmt(s.ratio,2)+' λⱼ';$('jeans-time-value').textContent=fmt(s.tau,2);document.querySelectorAll('[data-jeans]').forEach(b=>b.setAttribute('aria-pressed',String(Math.abs(+b.dataset.jeans-s.ratio)<1e-8)));const p=plot('jeans-chart',d3.scaleLinear().domain([0,3]),d3.scaleLinear().domain([-1.2,max]).nice(),'无量纲时间 τ','振幅 δ / δ₀');curve(p,data,d=>d.t,d=>d.d,C.gold);selected(p,s.tau,v.delta/.01);const regime={oscillating:'压力主导，模式振荡；负号表示原来的峰与谷互换。',marginal:'恰在临界波长；零初始速度使密度反差保持常数。',growing:'引力主导，初始静止的扰动按双曲余弦增长。'};$('jeans-result').textContent=`λ/λⱼ=${fmt(s.ratio,2)}，当前 δ=${fmt(v.delta,4)}（相对初始值 ${fmt(v.delta/.01,2)} 倍）。${regime[v.regime]}`;const {c,ctx,w,h}=canvas('jeans-wave'),col=d3.scaleLinear().domain([-.1,0,.1]).range([window.BookTheme.color('#63aebd'),window.BookTheme.color('#11222a'),window.BookTheme.color('#f1ce8c')]);for(let x=0;x<w;x++){const d=v.delta*Math.cos(TAU*(x/w*4-2)/s.ratio);ctx.fillStyle=col(d);ctx.fillRect(x,28,1,h-45);}ctx.fillStyle=window.BookTheme.color('#b5cecb');ctx.font='11px -apple-system,sans-serif';ctx.fillText('站波切片：横向范围 4λⱼ',12,16);c.setAttribute('aria-label',`Jeans站波：波长${fmt(s.ratio,2)}倍Jeans波长，当前振幅${fmt(v.delta,4)}。`);}
bind('jeans-ratio','ratio',jeans);bind('jeans-time','tau',()=>{stop('jeans-play');jeans();});document.querySelectorAll('[data-jeans]').forEach(b=>b.addEventListener('click',()=>{s.ratio=+b.dataset.jeans;$('jeans-ratio').value=s.ratio;save();jeans();}));$('jeans-play').addEventListener('click',()=>play('jeans-play','tau','jeans-time',0,3,jeans));
let growthSeries=[];
function cacheGrowth(){growthSeries=d3.range(161).map(i=>{const a=.05+i/160*.95;return P.growth(a,s.matter);});}
function growth(){
 const v=P.growth(s.a,s.matter),field=s.norm==='early'?'raw':'normalized',ratio=(1-v.omegaAtA)/v.omegaAtA;
 $('growth-matter-value').textContent=fmt(s.matter,2)+' · ΩΛ,₀='+fmt(1-s.matter,2);
 $('growth-a-value').textContent=fmt(s.a,3)+' · z='+fmt(1/s.a-1,2);
 $('growth-d-label').textContent=s.norm==='early'?'累计增长 D₊（早期统一）':'今日归一化 D̂ = D₊/D₊(1)';
 $('growth-d').textContent=fmt(v[field],6);$('growth-suppression').textContent=fmt(v.suppression,6);$('growth-f').textContent=fmt(v.f,6);$('growth-omega').textContent=fmt(v.omegaAtA,4);
 const p=plot('growth-chart',d3.scaleLinear().domain([.05,1]),d3.scaleLinear().domain([0,1.05]),'尺度因子 a',s.norm==='early'?'D₊：相同早期振幅':'D̂ = D₊ / D₊(1)');
 curve(p,[{a:.05},{a:1}],d=>d.a,d=>d.a,C.sage,'5 5');curve(p,growthSeries,d=>d.a,d=>d[field],C.gold);selected(p,s.a,v[field],C.gold,1);
 const stage=s.matter===1?'所选模型就是 EdS，D₊=a、f=1。':ratio<.01?'此时几乎是物质主导，增长很接近 EdS。':ratio<1?'此时物质密度仍较高，但相对 EdS 的抑制已经出现。':'此时 Λ 密度不低于物质密度，增长相对 EdS 的抑制更明显。';
 const normalization=s.norm==='early'?`相同早期振幅下，D₊ 是 EdS 的 ${fmt(v.suppression*100,2)}%。`:'今日对齐只改变振幅标尺；曲线早期较高不代表增长更快，f 与早期归一化的 D₊/a 都保持不变。';
 $('growth-result').textContent=`${normalization} 当前 ρΛ/ρm=${fmt(ratio,4)}。${stage}增长变慢不等于振幅下降：本范围内 D₊ 仍随 a 增加。`;
}

cacheGrowth();bind('growth-matter','matter',()=>{cacheGrowth();growth();});bind('growth-a','a',growth);$('growth-normalization').addEventListener('change',e=>{s.norm=e.target.value;save();growth();});
const columns=100,rows=24;
function sheet(){const {c,ctx,w,h}=canvas('sheet-canvas'),mobile=w<500,panels=mobile?[{x:10,y:28,w:w-20,h:120},{x:10,y:194,w:w-20,h:120}]:[{x:18,y:42,w:w/2-37,h:h-65},{x:w/2+19,y:42,w:w/2-37,h:h-65}];panels.forEach((r,i)=>{ctx.fillStyle=window.BookTheme.color('#9fbab9');ctx.font='11px -apple-system,sans-serif';ctx.fillText(i===0?'初始均匀分布':'位移后：共动坐标',r.x,r.y-13);for(let j=0;j<rows;j++)for(let n=0;n<columns;n++){const q=(n+.5)/columns-.5,v=P.zeldovich(q,i===0?0:s.strength),x=r.x+(v.x+.5)*r.w,y=r.y+(j+.5)/rows*r.h;ctx.fillStyle=i===0?window.BookTheme.color('#759c9ba0'):window.BookTheme.color('#e4c389b3');ctx.fillRect(x,y,mobile?1.1:1.5,mobile?1.1:1.5);}ctx.strokeStyle=window.BookTheme.color('#49646d');ctx.lineWidth=.5;ctx.strokeRect(r.x,r.y,r.w,r.h);});const center=P.zeldovich(0,s.strength);$('sheet-strength-value').textContent=fmt(s.strength,3);$('sheet-density').textContent=fmt(center.density,2);$('sheet-j').textContent=fmt(center.jacobian,3);$('sheet-count').textContent=(columns*rows).toLocaleString('zh-CN');$('sheet-result').textContent=`质量标记始终为 ${columns*rows} 个。中心映射的 J=${fmt(center.jacobian,3)}，因此中心密度为平均值的 ${fmt(center.density,2)} 倍。${s.strength>=.5?'密度已进入非线性范围；这里展示的是位移近似的外推。':'这是壳交叉前的单流压缩。'}首个壳交叉在 s=1。`;c.setAttribute('aria-label',`均匀分布与位移后的${columns*rows}个等质量标记，强度s=${fmt(s.strength)}，中心密度为平均值${fmt(center.density,2)}倍；未发生壳交叉。`);}
bind('sheet-strength','strength',()=>{stop('sheet-play');sheet();});$('sheet-play').addEventListener('click',()=>play('sheet-play','strength','sheet-strength',0,.9,sheet));
function transfer(){const k=10**s.logk,T=P.transfer(k,s.gamma),data=d3.range(181).map(i=>{const k=10**(-3+i/180*4),T=P.transfer(k,s.gamma);return {k,T,initial:k**s.n,processed:k**s.n*T*T};});$('transfer-gamma-value').textContent=fmt(s.gamma,3);$('transfer-k-value').textContent=sci(k);$('transfer-k').setAttribute('aria-valuetext',sci(k)+' h/Mpc');$('spectral-n-value').textContent=fmt(s.n,2);$('spectral-n').disabled=s.kind!=='power';$('spectral-n').closest('label').classList.toggle('range-disabled',s.kind!=='power');$('primordial-legend').hidden=s.kind!=='power';$('transfer-legend').textContent=s.kind==='T'?'T(k)':'经传递：kⁿT²(k)';const p=plot('transfer-chart',d3.scaleLog().domain([.001,10]),s.kind==='T'?d3.scaleLog().domain([.00001,1]):d3.scaleLog().domain([10**Math.floor(Math.log10(d3.min(data,d=>Math.min(d.initial,d.processed)))),10**Math.ceil(Math.log10(d3.max(data,d=>Math.max(d.initial,d.processed))))]),'k（h Mpc⁻¹）',s.kind==='T'?'振幅传递 T(k)':'谱形 / 任意幅度');if(s.kind==='power')curve(p,data,d=>d.k,d=>d.initial,C.sage,'5 5','初始功率谱 kⁿ');curve(p,data,d=>d.k,d=>s.kind==='T'?d.T:d.processed,C.gold,null,s.kind==='T'?'振幅传递函数 T(k)':'经过传递的功率谱 kⁿT²(k)');selected(p,k,s.kind==='T'?T:k**s.n*T*T,C.gold,s.kind==='T'?0:1);$('transfer-result').textContent=`所选 k=${sci(k)} h/Mpc，对应共动波长 λ=${fmt(TAU/k,1)} h⁻¹ Mpc。T=${sci(T)}；功率保留比例 T²=${sci(T*T)}。${s.kind==='power'?'两条谱使用同一任意初始幅度；曲线高低没有各自重新对齐。':'改变 Γ 会移动转折位置；这条近似曲线不含 BAO。'}`;}
bind('transfer-gamma','gamma',transfer);bind('transfer-k','logk',transfer);bind('spectral-n','n',transfer);$('transfer-kind').addEventListener('change',e=>{s.kind=e.target.value;save();transfer();});
window.PerturbationConcepts.slice(0,4).forEach(item=>{const article=document.createElement('article');article.className='concept-reading';const h=document.createElement('h3');h.textContent=item.title;const p=document.createElement('p');p.textContent=item.body;const caveat=document.createElement('p');caveat.className='concept-caveat';caveat.textContent=item.caveat;const ref=document.createElement('small');ref.textContent=item.section;article.append(h,p,caveat,ref);$('perturbation-concepts').append(article);});
window.PerturbationQuizzes.forEach(item=>{const row=document.createElement('article');row.className='quiz-item';const h=document.createElement('h3');h.textContent=item.q;const options=document.createElement('div');options.className='quiz-options';const feedback=document.createElement('p');feedback.className='quiz-feedback';feedback.setAttribute('aria-live','polite');item.options.forEach((option,i)=>{const b=document.createElement('button');b.textContent=option;b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>{options.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));feedback.textContent=(i===item.answer?'正确。':'再想一步。')+item.why;});options.append(b);});row.append(h,options,feedback);$('perturbation-quiz').append(row);});
function tutor(prompt){window.showTutor('我在学习 Mo, van den Bosch & White (2010)《Galaxy Formation and Evolution》第4章。'+prompt+' 请逐步解释物理意义，检查单位、初始条件与适用范围，并区分教材依据、教学近似和额外解释。不要把合成图当作观测数据。');}
$('tutor-open').addEventListener('click',()=>tutor('依据§4.1–4.5 pp.162–214，解释初始密度扰动、传递函数、增长因子与功率谱之间的关系，并给一道概念练习。'));
$('field-question').addEventListener('click',()=>tutor(`依据§4.4 pp.202–209，二维周期盒的16个固定幅度模式，密度反差均方根A=${fmt(s.amplitude)}，相位组${s.phase+1}。请解释为什么改变相位保留模式功率却改变地图。该示意没有高斯抽样振幅，不能称为严格高斯随机场。`));
$('jeans-question').addEventListener('click',()=>tutor(`依据§4.1.3 pp.166–167，静态均匀背景、固定声速，λ/λJ=${fmt(s.ratio,2)}，τ=${fmt(s.tau,2)}，δ(0)=0.01，dδ/dτ(0)=0，当前δ=${fmt(P.jeans(s.ratio,s.tau).delta,4)}。为何出现cos或cosh解？加入膨胀后需要改变什么？`));
$('growth-question').addEventListener('click',()=>tutor(`依据§4.1.6(a) pp.172–173，平直无压物质+Λ模型，Ωm,0=${s.matter}，ΩΛ,0=${1-s.matter}，a=${fmt(s.a)}，比较方式为${s.norm==='early'?'早期D/a→1统一归一化':'各模型D(1)=1'}，忽略辐射。请解释增长率f与D/a抑制因子，避免混淆不同归一化。`));
$('sheet-question').addEventListener('click',()=>tutor(`依据§4.1.8 pp.177–178，x=q−s sin(2πq)/(2π)，s=${fmt(s.strength)}，J(0)=${fmt(1-s.strength)}，中心ρ/ρbar=${fmt(1/(1-s.strength))}。请用质量守恒推导密度，并解释为何s=1后不能继续使用单流密度公式。本页是平面对称近似，不模拟维里化星系。`));
$('transfer-question').addEventListener('click',()=>tutor(`依据§4.3 pp.196–202（BBKS式4.245），Γ=${fmt(s.gamma)}，k=${sci(10**s.logk)} h/Mpc，n=${fmt(s.n,2)}，T=${sci(P.transfer(10**s.logk,s.gamma))}。请解释P∝k^n T²、T与T²的区别，以及低重子近似为何不能描述BAO。谱幅度任意，Γ不与前面增长模型自动绑定。`));
let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>{density();jeans();growth();sheet();transfer();},120);});density();jeans();growth();sheet();transfer();
})();
